const d = $input.all()[0].json;
const c = d.counts || {};
const today = new Date().toLocaleDateString('en-PH', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' });

const cancelled = (c['Cancelled by Client'] || 0) + (c['Cancelled by HP'] || 0);
const lost = (c['Dump'] || 0) + (c['NCNS'] || 0);
const active = (c['Confirmed'] || 0) + (c["Today's Booking"] || 0) + (c['Job In Progress'] || 0);
const forPayment = (c['FaceCard / For Downpayment'] || 0) + (c['Downpayment verification'] || 0) + (c['Full Payment Confirmation'] || 0);

return [{ json: {
  Date: today,
  Total: d.total || 0,
  New_Inquiry: c['New Inquiry'] || 0,
  HP_Applications: c['HP Applications'] || 0,
  For_Follow_Up: c['For Follow Up'] || 0,
  For_HP_Matching: c['For HP Matching'] || 0,
  Worker_Assigned: c['Worker assigned'] || 0,
  Assessment_Cleaning: c['Assessment/Quotation (Cleaning)'] || 0,
  Assessment_Skilled: c['Assessment/Quotation (Skilled)'] || 0,
  For_Payment: forPayment,
  Active_Bookings: active,
  Job_In_Progress: c['Job In Progress'] || 0,
  Completed_Month: d.completedThisMonth || 0,
  E_Receipt_Sent: c['E-Receipt Sent'] || 0,
  Cancelled: cancelled,
  Lost_Dump_NCNS: lost,
  Payment_Pipeline: d.paymentTotal || 0
} }];
